from fractions import Fraction as F

# K = {1/n : n a positive integer}. A basis for the K-topology consists of
#   (i)  open intervals (p, q), and
#   (ii) sets (p, q) \ K.

def in_K(x):
    # x is in K iff x = 1/n for some positive integer n
    if x <= 0:
        return False
    return (1 / x).denominator == 1

def witness(a, b, x):
    # Return a K-basis set U = (lo, hi) or (lo, hi) minus K with x in U and U inside (a, b).
    if not (a < x < b):
        return None
    if x != 0:
        # x != 0 lies in the open interval (a, b), which is itself a K-basis element.
        return ("interval", a, b, False)
    # x = 0 is not in K, so (-eps, eps) \ K is a K-basis set containing 0.
    eps = min(b, -a)  # positive because a < 0 < b
    return ("interval_minus_K", -eps, eps, True)

def check_witness(a, b, x, w):
    kind, lo, hi, minus_K = w
    # Containment (exact): (lo, hi) inside (a, b) because a <= lo and hi <= b.
    if not (a <= lo and hi <= b):
        return False
    if not (lo < x < hi):
        return False
    if minus_K and in_K(x):
        return False
    return True

def run():
    fracs = sorted({F(n, d) for d in range(1, 7) for n in range(-12, 13)})
    intervals = [(a, b) for a in fracs for b in fracs if a < b]

    # Also include tiny intervals around 0 and intervals with endpoints at 1/n.
    extra = [(F(-1, 3), F(1, 5)), (F(-1, 100), F(1, 100)), (F(0), F(1)),
             (F(-1), F(0)), (F(-1, 2), F(1, 2))]
    intervals += [e for e in extra if e not in intervals]

    total_pts = 0
    failures = []
    zero_cases = 0
    for a, b in intervals:
